def lower_bound(a: list[int], x: int) -> int:
    """First index i with a[i] >= x, or len(a). Same as bisect.bisect_left."""
    lo, hi = 0, len(a)                 # half-open [lo, hi)
    while lo < hi:
        mid = (lo + hi) // 2           # no overflow in Python; in Java/C++ use lo + (hi - lo) / 2
        if a[mid] < x:
            lo = mid + 1               # mid and everything left of it are too small
        else:
            hi = mid                   # mid might be the answer: keep it
    return lo

def min_ship_capacity(weights: list[int], days: int) -> int:
    def feasible(cap: int) -> bool:    # monotonic: if cap works, cap + 1 works
        used, load = 1, 0
        for w in weights:
            if load + w > cap:
                used, load = used + 1, 0
            load += w
        return used <= days

    lo, hi = max(weights), sum(weights)  # below max(w) the check would lie
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
